from common import *
rec,feat=init(); res=controls(feat)
st.title("Verification Risk")
m=st.radio("Metric",["euclidean","manhattan"],horizontal=True); t=res[m]["table"]; vc=t.risk_group.value_counts()
headline(f"{vc.get('High',0)} instruments are in the High-risk group, {vc.get('Medium',0)} Medium, {vc.get('Low',0)} Low. Risk groups are prioritisation aids, not legal findings of non-compliance.")
note("A 0–100 risk score per instrument and a Low / Medium / High grouping.","Score = weighted sum of 8 features rescaled to 0–1 (weights on 'How It Works'). Each cluster's level comes from the average score of its members: lowest = Low, highest = High, others = Medium.","The bar chart for an instrument shows exactly how many points each feature added.")
a,b=st.columns(2)
a.plotly_chart(px.pie(t,names="risk_group",template=T,color="risk_group",color_discrete_map={"Low":"#22d3ee","Medium":"#3b82f6","High":"#ef4444"},title="Risk groups"),use_container_width=True)
b.plotly_chart(px.box(t,x="risk_group",y="risk_score",template=T,category_orders={"risk_group":["Low","Medium","High"]},title="Score by group"),use_container_width=True)
st.write("**Top 10 priority instruments**"); st.dataframe(t.sort_values("risk_score",ascending=False).head(10)[["instrument_id","instrument_type","risk_score","risk_group","risk_reasons"]].round(1),use_container_width=True)
st.subheader("Why this score?")
iid=st.selectbox("Instrument",t.instrument_id); i=int(feat.index[feat.instrument_id==iid][0]); C=contributions(feat).iloc[i].sort_values(ascending=False)
st.plotly_chart(px.bar(C[::-1],orientation="h",template=T,labels={"value":"points","index":""}),use_container_width=True)
txt="; ".join(f"**{c}** = {feat[c].iloc[i]:.3g} (higher than {(feat[c]<=feat[c].iloc[i]).mean()*100:.0f}% of instruments, +{C[c]:.1f} pts)" for c in C.index[:3])
st.success(f"{iid}: {C.sum():.1f}/100 → **{t.risk_group.iloc[i]}**. Main drivers: {txt}.")
with st.expander("Full risk table"): st.dataframe(t,height=300)
